#!/usr/bin/env bash
# Generated by rulecloud sync-hooks — do not edit by hand.
set -euo pipefail

DIR="$(cd "$(dirname "$0")" && pwd)"
case "$DIR" in
  *"/.cursor/hooks")
    ROOT="$(cd "$DIR/../.." && pwd)"
    META="$ROOT/.cursor/hooks.json"
    ;;
  *"/.claude/hooks")
    ROOT="$(cd "$DIR/../.." && pwd)"
    META="$ROOT/.claude/settings.json"
    ;;
  *)
    echo "rulecloud-guard: unexpected hook path" >&2
    exit 2
    ;;
esac

RULES="$ROOT/.guardrail/rules.yml"
if [[ ! -f "$RULES" ]]; then
  echo "Missing .guardrail/rules.yml" >&2
  exit 2
fi

HASH="$(node -e "
const fs=require('fs');
const p=process.argv[1];
const j=JSON.parse(fs.readFileSync(p,'utf8'));
const h=j.rulecloud?.rulesSha256;
if(!h){process.exit(3);}
process.stdout.write(h);
" "$META" 2>/dev/null || true)"

if [[ -z "$HASH" ]]; then
  echo "Hook metadata missing rulecloud.rulesSha256 — run: rulecloud sync-hooks" >&2
  exit 2
fi

ACTUAL="$(openssl dgst -sha256 "$RULES" | awk '{print $NF}')"
if [[ "$HASH" != "$ACTUAL" ]]; then
  echo "Guardrail drift: .guardrail/rules.yml changed without hook sync. Run: rulecloud sync-hooks" >&2
  exit 2
fi

# Cursor/Claude hook payload (may be empty when invoked manually).
PAYLOAD="$(cat || true)"

# Block native file tools / shell when they target protected paths (e.g. .env).
# Heredoc keeps quotes/backticks out of bash parsing (node -e single-quotes break easily).
export RULECLOUD_HOOK_PAYLOAD="$PAYLOAD"
node <<'NODE'
const raw = process.env.RULECLOUD_HOOK_PAYLOAD || "";
let obj = {};
try { obj = raw ? JSON.parse(raw) : {}; } catch { obj = {}; }
const ti = (obj.tool_input && typeof obj.tool_input === "object") ? obj.tool_input : {};
const paths = [obj.file_path, obj.path, ti.file_path, ti.path]
  .filter((x) => typeof x === "string" && x.length > 0);
const command = [obj.command, ti.command]
  .filter((x) => typeof x === "string" && x.length > 0)
  .join("\n");

function baseName(p) {
  const n = String(p).replace(/\\/g, "/");
  const i = n.lastIndexOf("/");
  return i >= 0 ? n.slice(i + 1) : n;
}
function isProtectedPath(p) {
  const b = baseName(p);
  if (b === ".env") return true;
  if (b.startsWith(".env.") && b !== ".env.example") return true;
  return false;
}
for (const p of paths) {
  if (isProtectedPath(p)) {
    console.error("BLOCKED: refusing access to protected path: " + p);
    process.exit(2);
  }
}
if (command) {
  const tokens = command.split(/\s+/).map((t) => t.replace(/^["']+|["']+$/g, "")).filter(Boolean);
  for (const t of tokens) {
    if (isProtectedPath(t)) {
      console.error("BLOCKED: refusing access to protected path via command: " + t);
      process.exit(2);
    }
  }
}
NODE
unset RULECLOUD_HOOK_PAYLOAD

# Cursor preToolUse / beforeReadFile expect JSON on stdout when the hook succeeds.
if [[ "$META" == *".cursor/hooks.json" ]]; then
  echo '{"permission":"allow"}'
fi

exit 0
